<section class="admin-grid two"><article class="panel"><div class="panel-head"><div><span>LIVE OPERATIONS</span><h2>حالة الكتالوج</h2></div><a href="quality.php">مراجعة الجودة ←</a></div><div class="health-row"><div><span>المنتجات المنشورة</span><b><?=$s['published']?></b></div><div><span>المسودات</span><b><?=$s['drafts']?></b></div><div><span>تحتاج تحسين</span><b><?=count($low)?></b></div></div><div class="quality-bar"><i style="width:<?=max(0,min(100,(int)$s['quality']))?>%"></i></div></article><article class="panel"><div class="panel-head"><div><span>QUICK ACTIONS</span><h2>إجراءات سريعة</h2></div></div><div class="quick-grid"><a href="products.php">▦ إدارة المنتجات</a><a href="quotes.php">▤ مراجعة RFQ</a><a href="quality.php">◆ فحص البيانات</a><a href="settings.php">⚙ إعدادات النظام</a></div></article></section>
